import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"无领导小组讨论","description":"","frontmatter":{},"headers":[],"relativePath":"mianshi/wulingdao-xiaozu.md","filePath":"mianshi/wulingdao-xiaozu.md"}'),i={name:"mianshi/wulingdao-xiaozu.md"};function l(h,t,o,n,s,b){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="无领导小组讨论" tabindex="-1">无领导小组讨论 <a class="header-anchor" href="#无领导小组讨论" aria-label="Permalink to &quot;无领导小组讨论&quot;">​</a></h1><p>少数岗位采用，8-10 人一组，围绕给定问题讨论，考官全程观察评分。</p><h2 id="🔄-流程" tabindex="-1">🔄 流程 <a class="header-anchor" href="#🔄-流程" aria-label="Permalink to &quot;🔄 流程&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>材料阅读（5-10分钟）→ 个人陈述（每人2-3分钟）→ 自由讨论（20-30分钟）→ 总结汇报（3-5分钟）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="🎭-常见角色" tabindex="-1">🎭 常见角色 <a class="header-anchor" href="#🎭-常见角色" aria-label="Permalink to &quot;🎭 常见角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>职责</th><th>适合谁</th></tr></thead><tbody><tr><td>领导者</td><td>推动讨论节奏，明确讨论框架</td><td>逻辑清晰、敢于主导</td></tr><tr><td>时间控制者</td><td>把控各阶段时间，提醒跑题</td><td>细心、愿意服务</td></tr><tr><td>记录者</td><td>记录各人观点，总结形成共识</td><td>善于抓重点、写字快</td></tr><tr><td>观点贡献者</td><td>提出有质量的看法和建议</td><td>思维活跃</td></tr><tr><td>总结汇报者</td><td>向考官汇报讨论结果</td><td>表达清晰、逻辑强</td></tr></tbody></table><blockquote><p>💡 不用强求某个角色，自然发挥。讨论有贡献比角色重要！</p></blockquote><hr><h2 id="🎯-评分维度" tabindex="-1">🎯 评分维度 <a class="header-anchor" href="#🎯-评分维度" aria-label="Permalink to &quot;🎯 评分维度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>考官看什么</th></tr></thead><tbody><tr><td>参与度</td><td>是否积极发言？但不说废话</td></tr><tr><td>逻辑性</td><td>发言是否有条理？</td></tr><tr><td>协作性</td><td>是否尊重他人？是否推动共识？</td></tr><tr><td>影响力</td><td>观点是否被小组采纳？</td></tr><tr><td>表达力</td><td>清晰度、流畅度</td></tr></tbody></table><hr><h2 id="⚠️-注意事项" tabindex="-1">⚠️ 注意事项 <a class="header-anchor" href="#⚠️-注意事项" aria-label="Permalink to &quot;⚠️ 注意事项&quot;">​</a></h2><h3 id="✅-加分行为" tabindex="-1">✅ 加分行为 <a class="header-anchor" href="#✅-加分行为" aria-label="Permalink to &quot;✅ 加分行为&quot;">​</a></h3><ul><li>第一个发言，提出讨论框架</li><li>在争论时能调和矛盾</li><li>能把跑题拉回来</li><li>主动邀请没发言的组员说话</li><li>总结共识、推动进度</li></ul><h3 id="❌-扣分行为" tabindex="-1">❌ 扣分行为 <a class="header-anchor" href="#❌-扣分行为" aria-label="Permalink to &quot;❌ 扣分行为&quot;">​</a></h3><ul><li>一言不发（一定被淘汰）</li><li>强行打断别人</li><li>固执己见，无法妥协</li><li>人身攻击</li><li>话太多但无实质内容</li></ul><hr><h2 id="📐-常见讨论题型" tabindex="-1">📐 常见讨论题型 <a class="header-anchor" href="#📐-常见讨论题型" aria-label="Permalink to &quot;📐 常见讨论题型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>示例</th><th>思路</th></tr></thead><tbody><tr><td>排序题</td><td>从 10 项措施中选出最重要的 3 项</td><td>定标准 → 逐项评估 → 投票</td></tr><tr><td>方案题</td><td>设计一个工作方案</td><td>明确目标 → 列出步骤 → 分工</td></tr><tr><td>辩论题</td><td>城市管理应以疏为主还是以堵为主</td><td>先各自陈述 → 找共识点 → 综合</td></tr><tr><td>两难题</td><td>资源有限，项目 A 和 B 选哪个</td><td>设评价标准 → 量化对比 → 决策</td></tr></tbody></table><hr><h2 id="📝-练习记录" tabindex="-1">📝 练习记录 <a class="header-anchor" href="#📝-练习记录" aria-label="Permalink to &quot;📝 练习记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>题目</th><th>角色</th><th>表现自评</th><th>改进点</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table>',22)])])}const p=a(i,[["render",l]]);export{c as __pageData,p as default};
